validator:
function validate(input) {
  const [{ Students = [] }] = input;
  const ids = new Set();
  for (const [id, department, mark] of Students) {
    if (id === null || department === null || mark === null) return 'student_id, department_id and mark are required.';
    if (ids.has(id)) return `student_id ${id} appears twice.`;
    ids.add(id);
    if (mark < 0) return 'mark cannot be negative.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const Students = [];
  if (size === 'small') {
    // Few departments and few marks, so ties, single-student departments and empty tables all occur.
    const marks = [530, 610, 650, 700, 920];
    const count = pick(9), ids = [];
    for (let id = 1; id <= 12; id++) ids.push(id);
    for (let i = ids.length - 1; i > 0; i--) { const j = pick(i + 1); [ids[i], ids[j]] = [ids[j], ids[i]]; }
    for (let i = 0; i < count; i++) Students.push([ids[i], 1 + pick(3), marks[pick(marks.length)]]);
  } else {
    // Department sizes avoid 33, 65, 97 and 129, where a percentage could end in an exact half at the third decimal.
    let id = 0, department = 0;
    while (id < 1950) {
      let size = 1 + pick(120);
      if (size % 32 === 1 && size > 1) size++;
      department++;
      for (let k = 0; k < size && id < 2000; k++) Students.push([++id, department, pick(300)]);
    }
    for (let i = Students.length - 1; i > 0; i--) { const j = pick(i + 1); [Students[i], Students[j]] = [Students[j], Students[i]]; }
  }
  return [{ Students }];
}
